// === Tab: mySketch ===
/*
Hold down 'q' key while mouse dragging to change fractal parameter.
Hold down 'a' key while mouse dragging to pan image.
Hold down 'z' key while mouse dragging to zoom image.
Press Spacebar to toggle animation.
*/

let Shader;
let sliders = [];
let qKeyDown = false;
let aKeyDown = false;
let zKeyDown = false;
let animate = false;
let isDirty = true;
let cX = 0.2;
let cY = 0.3;
let centerX = 0.0;
let centerY = 0.0;
let zoom = 5.0;

function preload() {
	Shader = getShader(this._renderer);
}

let sliderY = 10;

function addSlider(name) {
	let n = createInput(name);
	n.size(70);
	n.style('font-size', '16px');
	n.style('background-color', color(0));
	n.style('color', color(255));
	n.position(10, sliderY);

	sliders.push(createSlider(0, 1000, 500));
	sliders[sliders.length - 1].position(100, sliderY);
	sliderY += 30;
}

function setup() {
	createCanvas(10,10, WEBGL);
	windowResized();

	addSlider("Speed");
	addSlider("C mult");
	addSlider("Z mult");
	addSlider("Contrast");
	addSlider("R Power");
	addSlider("G Power");
	addSlider("B Power");
	reset();
}

// ----------------------------------------------------
// canvas a little smaller than window to avoid scrollbars

function windowResized() {
	resizeCanvas(windowWidth - 10, windowHeight - 10);
	isDirty = true;
}

// ----------------------------------------------------
// auto-repeat direction of mouse dragging

var mx, my;
var mouseDX = 0.0;
var mouseDY = 0.0;
let isMouseDragging = false;

function mousePressed() {
	mx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
	my = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));
	isMouseDragging = true;
}

function mouseDragged() {
	mouseDX = -((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - mx) / 1000.0;
	mouseDY = ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - my) / 1000.0;
}

function mouseReleased() {
	mouseDX = 0.0;
	mouseDY = 0.0;
	isMouseDragging = false;
}

// ----------------------------------------------------

function keyPressed() {
	switch (key) {
		case 'q':
			qKeyDown = true;
			break;
		case 'a':
			aKeyDown = true;
			break;
		case 'z':
			zKeyDown = true;
			break;
		case ' ':
			animate = !animate;
			break;
		case 'r':
			reset();
			break;
	}
}

function keyReleased() {
	switch (key) {
		case 'q':
			qKeyDown = false;
			break;
		case 'a':
			aKeyDown = false;
			break;
		case 'z':
			zKeyDown = false;
			break;
	}
}

function reset() {
	cX = 0.42;
	cY = 0.27;
	centerX = 0.09;
	centerY = -0.25;
	zoom = 28.8;
	isDirty = true;

	//console.log("cX,Y: " + cX + "," + cY);
	//console.log("centerX,Y: " + centerX + "," + centerY + "," + zoom);
}

// ----------------------------------------------------

function sliderScaledValue(index, min, range) {
	return min + range * sliders[index].value() * 0.001;
}

// ----------------------------------------------------
let animateAngle = 0;

function draw() {
	if (isMouseDragging || animate) isDirty = true;
	if (!isDirty) return;
	isDirty = false;

	shader(Shader);

	// mouse dragging ------------------
	if (qKeyDown) {
		cX += mouseDX * 0.1;
		cY += mouseDY * 0.1;
	}
	if (aKeyDown) {
		let zoomScale = zoom * 0.01;
		centerX += mouseDX * zoomScale;
		centerY += mouseDY * zoomScale;
	}
	if (zKeyDown) {
		zoom *= 1.0 + mouseDX * 0.05;
	}

	if (animate)
		animateAngle += sliderScaledValue(0, 0.1, 2.0) * 0.01; // speed slider
	let finalX = cX + sin(animateAngle) * 0.01;
	let finalY = cY + cos(animateAngle) * 0.01;
	Shader.setUniform('c', [finalX, finalY]);

	Shader.setUniform('centerX', centerX);
	Shader.setUniform('centerY', centerY);
	Shader.setUniform('zoom', zoom);
	Shader.setUniform('cmult', sliderScaledValue(1, 0.95, 0.1));
	Shader.setUniform('zmult', sliderScaledValue(2, 0.8, 0.4));
	Shader.setUniform('contrast', sliderScaledValue(3, 0.01, 1.0));
	Shader.setUniform('rPower', sliderScaledValue(4, 0.02, 2.0));
	Shader.setUniform('gPower', sliderScaledValue(5, 0.5, 8.0));
	Shader.setUniform('bPower', sliderScaledValue(6, 1.0, 12.0));

	rect(0, 0, width, height);
}

function getShader(_renderer) {
	const frag = `
		precision highp float;
		varying vec2 vTexCoord;
		uniform sampler2D pal;
		uniform vec2 c;
		uniform float cmult,zmult,contrast,rPower,gPower,bPower;
		uniform float centerX,centerY,zoom;

		const float zh=${windowHeight/windowWidth};
		float o2,orbit = 9999.0,orbit2 = 0.0;

		float applyContrast(float value) {
		  if(value < 0.5) value *= 0.02;			
			value = 0.5 + log(value);			
			return 0.5 + (value - 0.5) * contrast;
		}

		void main() {
			vec2 cc = c;
			float zoom2 = zoom * 0.5;
			float sx = centerX + zoom * vTexCoord.x - zoom2;
			float sy = (centerY + zoom * vTexCoord.y - zoom2) * zh;

			vec2 z=vec2(sx,sy);
			int iter=1000;

			z *= 0.3;

			for(int i=0;i<100;i++) {
				float x=(z.x+z.y)*(z.x-z.y)+cc.x;
				float y=2.*z.y*z.x+cc.y;
				if((x*x+y*y)>4.) {iter=i;break;}
				z.x=x;
				z.y=y;

				o2 = length(z);
				if(o2 < orbit) {
					orbit = o2;
					orbit2 = (orbit2 == 0.0) ? o2 : (orbit2 * 3.0 + o2) / 4.0;
				}

				cc.x *= cmult;
				cc.y *= cmult;
				z *= zmult;
			}

			float cr = 0.0;
			float cg = 0.0;
			float cb = 0.0;

			// put whatever you can think of here
			if(iter < 1000) {
				cr = log(float(iter) * 50.1) * rPower;
				cg = 1.0 - pow(orbit, gPower) * 5.0;
				cb = orbit2 * bPower * cg / cr;
			}

			gl_FragColor = vec4(applyContrast(cr),applyContrast(cg),applyContrast(cb),1);
		}
	`;

	const vert = `
		precision highp float;
		attribute vec3 aPosition;
		attribute vec2 aTexCoord;
		varying vec2 vTexCoord;
		void main() {
			vTexCoord=aTexCoord;
			vec4 positionVec4=vec4(aPosition,1.);
			positionVec4.xy=positionVec4.xy*2.-1.; 
			gl_Position=positionVec4;
		}
	`;

	return createShader(vert, frag);
}

